// Resolves the identifier 'Derived' used as default value in the header parameter list
localparam int Derived = PARA_APBCDC_DATA_W / 8;

// helper registers (clock domain: i_clk_mst)
logic chk006_armed;
logic chk006_prev_setup;
logic chk008_rd_op;

always_ff @(posedge i_clk_mst) begin
  if (!i_rst_n_mst) begin
    chk006_armed      <= 1'b0;
    chk006_prev_setup <= 1'b0;
    chk008_rd_op      <= 1'b0;
  end else begin
    chk006_prev_setup <= (i_apb_psel && !i_apb_penable);
    if (i_apb_psel && !i_apb_penable) begin
      chk006_armed <= 1'b1;
      chk008_rd_op <= !i_apb_pwrite;
    end else if (o_apb_pready) begin
      chk006_armed <= 1'b0;
    end
  end
end

// CHK-003: Requester-side PREADY only in an Access cycle (AB2-15.3-02, AB2-3-08, AB2-6.3-04, AB2-20.2-06, AB2-2.3-01)
a_CHK_003: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst)
  (i_rst_n_slv && o_apb_pready) |-> (i_apb_psel && i_apb_penable))
  else begin fails_CHK_003++; $display("NNC_FAIL CHK-003 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_rst_n_slv && o_apb_pready)) hits_CHK_003 <= hits_CHK_003 + 1;

// CHK-004: Requester-side PREADY is a one-cycle pulse (AB2-3-08, AB2-15.3-03, AB2-10.1-04, AB2-5.4-04)
a_CHK_004: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst)
  (i_rst_n_slv && o_apb_pready) |=> (!o_apb_pready && !o_apb_pslverr))
  else begin fails_CHK_004++; $display("NNC_FAIL CHK-004 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_rst_n_slv && o_apb_pready)) hits_CHK_004 <= hits_CHK_004 + 1;

// CHK-005: PSLVERR only in the PREADY cycle (AB2-3-11, AB2-3-23, AB2-15.3-04, AB2-6.2-01, AB2-6.3-09, AB2-12-08, AB2-10.1-04)
a_CHK_005: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst)
  (i_rst_n_slv && o_apb_pslverr) |-> o_apb_pready)
  else begin fails_CHK_005++; $display("NNC_FAIL CHK-005 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_rst_n_slv && o_apb_pslverr)) hits_CHK_005 <= hits_CHK_005 + 1;

// CHK-006: At most one PREADY per accepted Setup phase (AB2-3-07, AB2-15.3-03, AB2-5.4-04, AB2-10.1-02)
a_CHK_006: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst)
  (i_rst_n_slv && (o_apb_pready || (i_apb_psel && !i_apb_penable))) |->
    (!o_apb_pready || (chk006_armed && !(i_apb_psel && !i_apb_penable) && !chk006_prev_setup)))
  else begin fails_CHK_006++; $display("NNC_FAIL CHK-006 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_rst_n_slv && (o_apb_pready || (i_apb_psel && !i_apb_penable)))) hits_CHK_006 <= hits_CHK_006 + 1;

// CHK-007: Response outputs stable outside the PREADY cycle (AB2-3-22)
a_CHK_007: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst)
  (i_rst_n_slv && !o_apb_pready) |->
    ($stable(o_apb_prdata) && $stable(o_apb_pruser) && $stable(o_apb_pbuser)))
  else begin fails_CHK_007++; $display("NNC_FAIL CHK-007 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_rst_n_slv && !o_apb_pready)) hits_CHK_007 <= hits_CHK_007 + 1;

// CHK-008: No unknown requester-side outputs after reset (AB2-15.3-18, AB2-6.3-05)
a_CHK_008: assert property (@(posedge i_clk_mst) disable iff (!i_rst_n_mst)
  i_rst_n_slv |->
    (!$isunknown({o_apb_pready, o_apb_pslverr, o_apb_prdata, o_apb_pruser, o_apb_pbuser}) &&
     (!(o_apb_pready && chk008_rd_op) || !$isunknown(o_apb_prdata))))
  else begin fails_CHK_008++; $display("NNC_FAIL CHK-008 @%0t", $time); end
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_rst_n_slv)) hits_CHK_008 <= hits_CHK_008 + 1;
